import{c as a,Q as l,j as e,m as s}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"SyncAll","description":"","frontmatter":{},"headers":[{"level":1,"title":"SyncAll","slug":"syncall"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/同步控制/核间同步/SyncAll.md","filePath":"api/SIMD-API/基础API/同步控制/核间同步/SyncAll.md"}'),n={name:"api/SIMD-API/基础API/同步控制/核间同步/SyncAll.md"};function o(i,t,d,r,c,p){return l(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="syncall" tabindex="-1">SyncAll <a class="header-anchor" href="#syncall" aria-label="Permalink to &quot;SyncAll&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持（软同步原型）</th><th>是否支持（硬同步原型）</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>当不同核之间操作同一块全局内存且可能存在读后写、写后读以及写后写等数据依赖问题时，通过调用该函数来插入同步语句来避免上述数据依赖时可能出现的数据读写错误问题。目前多核同步分为硬同步和软同步，硬件同步是利用硬件自带的全核同步指令由硬件保证多核同步，软件同步是使用软件算法模拟实现。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>软同步</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool isAIVOnly = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void SyncAll(const GlobalTensor&lt;int32_t&gt;&amp; gmWorkspace, const LocalTensor&lt;int32_t&gt;&amp; ubWorkspace, const int32_t usedCores = 0)</span></span></code></pre></div></li><li><p>硬同步</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool isAIVOnly = true, const SyncAllConfig&amp; config = DEFAULT_SYNC_ALL_CONFIG&gt;</span></span>
<span class="line"><span>__aicore__ inline void SyncAll()</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>isAIVOnly</td><td>控制SyncAll作用于纯Vector算子或融合（Cube和Vector融合）算子。可选值： true（默认值）：纯Vector算子的全核同步，仅执行Vector核的全核同步。false：融合算子的全核同步，先分别完成Vector核和Cube核的全核同步，再执行两者之间的同步（软同步接口不支持此功能）。</td></tr><tr><td>config</td><td>控制SyncAll函数的行为 ，在多个AI Core之间进行流水线同步时，指定哪些管道（pipe）用于触发和等待。 triggerPipe：指定哪个管道用于“发送触发信号”。waitPipe：指定哪个管道用于“接收等待信号”。 默认为SyncAllConfig DEFAULT_SYNC_ALL_CONFIG= {PIPE_ALL, PIPE_ALL} ，使用全部管道来进行触发和等待行为。 该参数仅支持如下型号： Ascend 950PR/Ascend 950DT</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>gmWorkspace</td><td>输入</td><td>gmWorkspace为用户定义的全局Global空间，作为所有核共用的缓存，用于保存每个核的状态标记，类型为GlobalTensor，支持的数据类型为int32_t。GlobalTensor数据结构的定义请参考GlobalTensor。 所需空间大小和使用注意项参见约束说明。 硬同步接口不支持该参数。</td></tr><tr><td>ubWorkspace</td><td>输入</td><td>ubWorkspace为用户定义的局部Local空间，每个核单独自用，用于标记当前核的状态。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT，支持的数据类型为int32_t。 所需空间大小参见约束说明。 硬同步接口不支持该参数。</td></tr><tr><td>usedCores</td><td>输入</td><td>指定多少个核之间的同步，传入数值不能超过算子调用时指定的逻辑numBlocks。此参数为默认参数，不传此参数表示全核软同步。 仅在软同步接口中支持，硬同步接口不支持该参数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>gmWorkspace缓存申请的空间大小要求大于等于核数*32Bytes，并且缓存的值需要初始化为0。目前常见的有两种初始化方式：</p><ul><li>通过在host侧进行初始化操作，确保传入该接口时，gmWorkspace缓存已经初始化为0；</li><li>在kernel侧初始化的时候对gmWorkspace缓存初始化，需要注意的是，每个核上都需要初始化全部的gmWorkspace缓存空间。</li></ul></li><li><p>ubWorkspace申请的空间大小要求大于等于核数*32Bytes。</p></li><li><p>针对Ascend 950PR/Ascend 950DT，对于软同步接口，连续使用（Polling）该接口，用于进行多核同步，会造成Bus被长期占用，导致其他核无法访问该GM，导致多核读同一GM出现卡死现象，若需要Polling，建议在该使用接口间，增加Nop指令，指令量建议为800个，一般为需要同步的核数 * 200。</p></li><li><p>使用该接口进行多核控制时，算子调用时指定的逻辑numBlocks必须保证不大于实际运行该算子的AI处理器核数，否则框架进行多轮调度时会插入异常同步，导致Kernel“卡死”现象。</p></li><li><p>SyncAll硬件同步接口内部实现中使用了<a href="./CrossCoreSetFlag(ISASI).html">CrossCoreSetFlag</a>进行核间同步控制，所以不建议开发者同时使用CrossCoreSetFlag和SyncAll硬件同步接口接口，否则会有flagID冲突的风险。SyncAll硬件同步接口flagId占用范围为[11-14]。</p></li><li><p>在分离模式下，建议使用硬同步接口而非软同步接口。软同步接口仅适用于纯Vector场景，且性能较低。使用硬同步接口时，需根据场景设置Kernel类型：</p><ul><li>在纯Vector/Cube场景下，需设置Kernel类型为KERNEL_TYPE_MIX_AIV_1_0或KERNEL_TYPE_MIX_AIC_1_0。</li><li>对于Vector和Cube混合场景，需根据实际情况灵活配置Kernel类型。</li></ul></li><li><p>使用该接口时，建议开启batchmode模式，使算子独占全部所需核资源，否则可能因满足以下条件导致死锁：</p><ul><li>多流并发场景（≥2条执行流）。</li><li>≥2个算子并发执行。</li><li>所有并发算子的核数总和超过物理核数。</li><li>≥2个并发算子使用了核间同步功能。</li></ul><p>具体而言，在多流场景下，某条流的核间同步算子虽分配到n个物理核，但可能仅有n-m个核先被调度执行，而其余m个核因被其他流的核间同步算子抢占而尚未启动。先启动的n-m个核执行到核间同步时等待剩余m核完成，而剩余m核因被其他流的核间同步算子占用而无法释放，形成死锁。</p><p>Kernel直调场景下通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/guide/%E7%BC%96%E7%A8%8B%E6%8C%87%E5%8D%97/%E8%AF%AD%E8%A8%80%E6%89%A9%E5%B1%95%E5%B1%82/SIMD-BuiltIn%E5%85%B3%E9%94%AE%E5%AD%97.md" target="_blank" rel="noreferrer">__schedmode__(mode)</a>限定符来设置batchmode模式；工程化算子开发场景下，通过TilingContext的SetScheduleMode接口来设置batchmode模式，具体请参考《基础数据结构和接口》。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本示例实现功能为使用8个核进行数据处理，每个核均是处理32个float类型数据，对该数据乘2后再与其他核上进行同样乘2的数据进行相加，中间结果保存到workGm，因此多个核之间需要进行数据同步。此样例中，使用软同步，入口函数传入的syncGm里的值都已经在host侧初始化为0。若以下用例改成使用硬同步，则不需要传入syncGm，并且不需要使用workQueue。如需运行，请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/06_sync_control/sync_all" target="_blank" rel="noreferrer">SyncAll样例</a>实现完整的代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>...</span></span>
<span class="line"><span>// syncGlobal为用户定义的全局Global空间，作为所有核共用的缓存，类型为GlobalTensor；workLocal为用户定义的局部Local空间，每个核单独自用，类型为LocalTensor</span></span>
<span class="line"><span>int srcDataSize = 256; // 参与计算的元素个数</span></span>
<span class="line"><span>int32_t blockNum = AscendC::GetBlockNum(); // 获取核总数</span></span>
<span class="line"><span>int32_t blockIdx = AscendC::GetBlockIdx(); // 获取当前工作的核ID</span></span>
<span class="line"><span>uint32_t perBlockSize = srcDataSize / blockNum; // 每个核平分处理相同个数</span></span>
<span class="line"><span>// 当前工作核计算后的数据先保存到外部工作空间，workGlobal为GlobalTensor，dstLocal为LocalTensor</span></span>
<span class="line"><span>AscendC::DataCopy(workGlobal[blockIdx * perBlockSize], dstLocal, perBlockSize);</span></span>
<span class="line"><span>// 等待所有核都完成计算</span></span>
<span class="line"><span>AscendC::SyncAll(syncGlobal, workLocal);</span></span>
<span class="line"><span>...</span></span></code></pre></div>`,19)])])}const u=a(n,[["render",o]]);export{b as __pageData,u as default};
